import { useCallback, useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const isSameDay = (a: Date | null, b: Date | null) =>
  a != null && b != null && startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(defaultValue);

  const presets = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', getDate: () => shiftDays(0) },
      { id: 'yesterday', label: 'Вчера', getDate: () => shiftDays(1) },
      { id: 'week-ago', label: 'Неделя назад', getDate: () => shiftDays(7) },
    ],
    [],
  );

  const apply = useCallback(
    (value: Date | null) => {
      setDate(value);
      onChange?.(value);
    },
    [onChange],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', fontFamily: 'var(--jx-font-sans)' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(date, preset.getDate());
          return (
            <JxChip
              key={preset.id}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              active={active}
              onClick={() => apply(preset.getDate())}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  apply(preset.getDate());
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale="ru-RU" value={date} onValueChange={apply} aria-label="Дата отчёта" />

      <p style={{ margin: 0, color: 'var(--jx-text-2)' }} aria-live="polite">
        {date
          ? `Дата отчёта: ${date.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше.'}
      </p>
    </div>
  );
}

